ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2 NOT UserName=/\$$/
| (
    (ImageFileName=/\\vssadmin\.exe$/i CommandLine=/delete.*shadows/i)
    or (ImageFileName=/\\bcdedit\.exe$/i CommandLine=/recoveryenabled\s+no/i)
    or (ImageFileName=/\\wbadmin\.exe$/i CommandLine=/delete.*catalog/i)
    or (ImageFileName=/\\(powershell|pwsh)\.exe$/i CommandLine=/(set|add)-mppreference/i CommandLine=/(exclusionpath|exclusionprocess|exclusionextension|disablerealtimemonitoring|disableioavprotection)/i)
    or (ImageFileName=/\\sc\.exe$/i CommandLine=/config/i CommandLine=/(windefend|msmpsvc|sense|wdnissvc)/i CommandLine=/disabled/i)
    or (ImageFileName=/\\net\.exe$/i CommandLine=/\bstop\b/i CommandLine=/(windefend|msmpsvc|sense)/i)
  )
| Technique := if(ImageFileName=/vssadmin/i, "shadow-delete",
              if(ImageFileName=/bcdedit/i, "recovery-disable",
              if(ImageFileName=/wbadmin/i, "backup-delete",
              if(ImageFileName=/(powershell|pwsh)/i, "defender-tamper",
              if(ImageFileName=/sc\.exe/i, "service-disable",
              if(ImageFileName=/net\.exe/i, "service-stop", "other"))))))
| groupBy([aid, ComputerName, UserName, bucket(span=30m)], function=[count(field=Technique, as=TechCount, distinct=true), collect([Technique]), collect([CommandLine], limit=8), collect([ParentBaseFileName], limit=6)])
| TechCount >= 2

ucs.datadog_query:
source:windows.sysmon @EventID:11 (
  @TargetFilename:(*.MEDUSA OR *.Medusa OR *.medusa)
  OR @TargetFilename:(*READ_ME_MEDUSA*.txt OR *read_me_medusa*.txt OR *Read_Me_Medusa*.txt)
)
